// Built once at load: canonical name (lowercase) -> [alias, alias, ...], so a search
// term can be matched against every alias for a tag in O(1) per tag, not a full scan.
const ALIASES_BY_CANONICAL = {};
for (const [alias, canonical] of TAG_ALIASES) {
  const key = canonical.toLowerCase();
  (ALIASES_BY_CANONICAL[key] ||= []).push(alias.toLowerCase());
}

// True if `needle` (already lowercased by the caller) matches any alias of `canonicalName`
// (the raw underscore-form tag name as stored in data.js). Used by the Tag Library search
// to find a tag via "pigtails" when the real tag is "twintails", etc.
function tagMatchesAlias(canonicalName, needle) {
  const aliases = ALIASES_BY_CANONICAL[String(canonicalName).toLowerCase()];
  if (!aliases) return false;
  return aliases.some((a) => a.includes(needle));
}
